class UserBuilder:
    def __init__(self):
        self._name: Optional[str] = None
        self._age: Optional[int] = None
        self._email: Optional[str] = None

    def set_name(self, name: str) -> "UserBuilder":
        self._name = name
        return self

    def set_age(self, age: int) -> "UserBuilder":
        self._age = age
        return self

    def set_email(self, email: str) -> "UserBuilder":
        self._email = email
        return self

    def build(self) -> Dict[str, Union[str, int]]:
        if not all([self._name, self._age, self._email]):
            raise ValueError("Missing required fields")
        return {"name": self._name, "age": self._age, "email": self._email}

user = (
    UserBuilder().set_name("Alice").set_age(30).set_email("alice@example.com").build()
)

print(f"Built user: {user}")

